        if 'several occasions' in w and 'both children' in w and 'home' in w and 'sitter' in w:
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'OI-205':
        if 'school' in w and 'clinicians' in w and ('babysitter' in w or 'sitter' in w) and ('neighbour' in w or 'neighbor' in w):
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'OI-206':
        if 'position' in w and ('violate' in w or 'contravene' in w or 'appreciate' in w or 'order' in w):
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'CL-309':
        if 'violate' in w or 'contravene' in w or 'appreciate' in w or 'no concern' in w or 'not concerned' in w:
            return 'AT_ODDS'
        if 'position' in w:
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'OI-207':
        if 'confidence' in w and 'stability' in w and (
            'set back' in w or 'set it back' in w or 'set that plan back' in w or 'set the plan back' in w or 'set her back' in w
        ):
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'CL-308':
        if 'confidence' in w and 'stability' in w and 'peer' in w and (
            'confidence alone' in w or 'confidence only' in w or 'confidence, the only' in w or 'confidence, the aspect' in w
        ):
            return 'VERIFIED'
        return 'AT_ODDS'

    if g in ('OI-208', 'CL-302'):
        if 'meeting' in w or 'post to counsel' in w or 'by post' in w:
