        if 'certified copy' in w and 'custodial plan' in w:
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'CL-304':
        if 'dear counsel' in w:
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'CL-305':
        if 'do not copy anyone' in w or 'nobody is copied' in w or 'no copy line' in w or ('nobody' in w and 'copy' in w):
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'CL-306':
        if 'post' in w and 'hand' not in w and 'courier' not in w and 'email' not in w:
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'CL-307':
        if 'firm' in w and 'formal' in w and 'brief' in w:
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'OI-210':
        if 'soft' in w and 'formal' in w and 'succinct' in w:
            return 'VERIFIED'
        return 'AT_ODDS'

    if g == 'CL-310':
        if 'confidence' in w and 'stability' in w and 'peer' in w and (
            'together' in w or 'all' in w or 'jointly' in w or 'same time' in w or 'rather than picking one' in w
        ):
